exploreUrl:
@js:
var result = [];
var push = (title, url, size) => result.push({
    title: java.t2s(title),
    url: url && /_/.test(url) ? `/novels/${url}.html` : url,
    style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: size
    }
});

push("全部分类", null, 1);

const tag = org.jsoup.Jsoup.parse(java.ajax(source.key + "/novels/hot")).select('.droplist li:not([class]) a');
const sort = [
    ["连载", "newhot_0_0_1"],
    ["全本", "newhot_0_1_1"],
    ["人气", "weekvisit_0_0_1"],
    ["推荐", "allvote_0_0_1"]
];

sort.forEach(([name, pattern]) => {
    let Url = pattern.replace(/1$/, "{{page}}");
    push(`༺ˇ»\`ʚ  ${name}  ɞ´«ˇ༻`, Url, 1);
    tag.toArray().forEach((e, i) => push(e.text(), Url.replace(/^(.+?_)0/, `$1${i+1}`), 0.25));
});

push("༺ˇ»`ʚ  标签  ɞ´«ˇ༻", null, 1);
org.jsoup.Jsoup.parse(java.ajax(source.key)).select('.tag a').forEach(n => 
    push(n.text(), n.attr('href') + "/{{page}}", 0.2)
);

JSON.stringify(result);

